package day1;

public class Program2_DatatypeBasic {
	
	public static void main(String[] args) {
		// TODO Auto-generated method stub
		
		int num=987654321;
		System.out.println("int takes 4 bytes : "+num);
		
		boolean result=true;
		System.out.println("boolean takes 1 bit : "+result);
		
		byte data=-128;//-128 to 127 it can store
		System.out.println("byte takes 1 bytes : "+data);
		
		char alpha='A';
		System.out.println("char takes 2 bytes : "+alpha);
		
		short answer=-32768;
		System.out.println("short takes 2 bytes : "+answer);
		
		float marks=12.345678912F;
		System.out.println("float takes 4 bytes : "+marks);
		
		float marks2=1234.5678912F;
		System.out.println("float takes 4 bytes : "+marks2);
		
		float marks3=123456.78912F;
		System.out.println("float takes 4 bytes : "+marks3);
		
		long phoneNumber=987654320987L;
		System.out.println("long takes 8 bytes : "+phoneNumber);
		
		double dblMarks=12.345678912;
		System.out.println("double takes 8 bytes : "+dblMarks);
		
		double dblMarks2=1234.5678912;
		System.out.println("double takes 8 bytes : "+dblMarks2);
		
		double dblMarks3=123456.78912;
		System.out.println("double takes 8 bytes : "+dblMarks3);

	}


}
